export const LIVESTOCK_SPECIES = species;

// These are discrete minimum viable production units, not fractional nutrient
// knobs. A smaller scale may be useful for a sensitivity calculation, but it
// cannot represent a self-replacing ARC population.
export const MINIMUM_SELF_REPLACING_SYSTEMS = {
  rabbit_meat: {minimum_scale: 1, label: 'Minimum self-replacing rabbit colony', breeding_does: 4, breeding_bucks: 1},
  chicken_eggs: {minimum_scale: 1, label: 'Minimum self-replacing dual-purpose chicken flock', breeding_hens: 8, breeding_roosters: 1},
  goose_meat: {minimum_scale: 1, label: 'Minimum self-replacing goose flock', breeding_females: 3, breeding_males: 1},
  goat_meat: {minimum_scale: 1, label: 'Minimum self-replacing goat herd', breeding_does: 2, breeding_bucks: .25}
};

const whole = (value) => Math.max(0, Math.round(Number(value)));
const activeWhole = (value, scale) => Number(scale) > 0 ? Math.max(1, whole(value)) : 0;

export function deriveLivestockScale({foodDemandGJYear, livestockMode = 'plants_only', livestockScale} = {}) {
  if (livestockMode === 'plants_only') return 0;
  if (livestockScale !== undefined && livestockScale !== null) return Math.max(0, Number(livestockScale));
  const foodAdultEquivalents = Number(foodDemandGJYear ?? 0) / FOOD_ADULT_EQUIVALENT_GJ_YEAR;
  return Math.max(0, foodAdultEquivalents / CANONICAL_HOUSEHOLD_FAE);
}

// Kept as a compatibility export. It now reports selected system bases, not
// a number of complete systems generated by household size.
export function deriveLivestockSystemCount({livestockMode = 'plants_only'} = {}) {
  if (livestockMode === 'plants_only') return 0;
  return livestockMode === 'mixed_rabbit_eggs' ? 2 : 1;
}

function livestockPopulation(speciesId, scale = 1) {
  const factor = Math.max(0, Number(scale));
  const active = factor > 0;
  const reproduction = LIVESTOCK_SPECIES[speciesId]?.reproduction ?? {};
  if (speciesId === 'rabbit_meat') {
    const baseDoes = Number(reproduction.breeding_does ?? 4);
    const littersPerDoe = Number(reproduction.litters_year ?? 4);
    const kitsPerLitter = Number(reproduction.kits_per_litter ?? 7);
    const breedingFemales = activeWhole(baseDoes * factor, factor);
    const breedingMales = active ? Math.max(1, Math.ceil(breedingFemales / 8)) : 0;
    const litters = breedingFemales * littersPerDoe;
    const kitsBorn = litters * kitsPerLitter;
    const kitsSurviving = whole(kitsBorn * Number(reproduction.kit_survival ?? .75));
    const replacementFemales = active ? Math.max(1, whole(Number(reproduction.replacement_does_year ?? 1) * breedingFemales / baseDoes)) : 0;
    const replacementMales = active ? Number(reproduction.replacement_bucks_year ?? .25) * (breedingFemales / baseDoes) : 0;
    const harvestable = Math.max(0, kitsSurviving - replacementFemales - replacementMales);
    const canonicalHarvestable = 84 - 1 - .25;
    return {breeding_females: breedingFemales, breeding_males: breedingMales, litters_year: litters, kits_born_year: kitsBorn, kits_surviving_year: kitsSurviving, replacement_females_year: replacementFemales, replacement_males_year: replacementMales, animals_available_for_harvest_year: harvestable, feed_scale: breedingFemales / baseDoes, output_scale: harvestable / canonicalHarvestable, housing_scale: (breedingFemales + breedingMales) / 5, buck_capacity_does: 8, buck_capacity_note: 'One breeding buck is retained through eight does before an additional buck is planned.'};
  }
  if (speciesId === 'chicken_eggs') {
    const baseHens = Number(reproduction.breeding_hens ?? 8);
    const breedingFemales = activeWhole(baseHens * factor, factor);
    const breedingMales = active ? Math.max(1, Math.ceil(breedingFemales / 8)) : 0;
    const incubationEggs = active ? Math.max(1, whole(Number(reproduction.incubation_eggs_year ?? 24) * breedingFemales / baseHens)) : 0;
    const chicks = incubationEggs * Number(reproduction.hatch_rate ?? .80) * Number(reproduction.juvenile_survival ?? .85);
    const females = chicks * Number(reproduction.female_chick_fraction ?? .5);
    const males = chicks * (1 - Number(reproduction.female_chick_fraction ?? .5));
    const replacementFemales = active ? Math.max(1, whole(Number(reproduction.replacement_hens_year ?? 4) * breedingFemales / baseHens)) : 0;
    const replacementMales = active ? Math.max(1, whole(Number(reproduction.replacement_roosters_year ?? 1) * breedingMales)) : 0;
    const surplusMales = Math.max(0, males - replacementMales);
    const surplusFemales = Math.max(0, females - replacementFemales);
    const grossEggs = breedingFemales * Number(reproduction.eggs_per_hen_year ?? 180);
    const edibleEggs = Math.max(0, (grossEggs - incubationEggs) * (1 - Number(reproduction.egg_loss_fraction ?? .03)));
    const edibleMeat = surplusMales * Number(reproduction.surplus_cockerel_edible_meat_kg ?? 1) + surplusFemales * Number(reproduction.cull_hen_edible_meat_kg ?? 1) + replacementMales * Number(reproduction.cull_rooster_edible_meat_kg ?? .8);
    return {breeding_females: breedingFemales, breeding_males: breedingMales, fertile_eggs_year: incubationEggs, eggs_incubated_year: incubationEggs, chicks_hatched_and_surviving_year: chicks, replacement_females_year: replacementFemales, replacement_males_year: replacementMales, surplus_males_year: surplusMales, surplus_females_year: surplusFemales, gross_eggs_year: grossEggs, edible_eggs_year: edibleEggs, edible_eggs_kg_year: edibleEggs * Number(reproduction.egg_mass_kg ?? .05), edible_meat_kg_year: edibleMeat, feed_scale: breedingFemales / baseHens, output_scale: breedingFemales / baseHens, housing_scale: (breedingFemales + breedingMales) / 9, rooster_capacity_hens: 8, rooster_capacity_note: 'One breeding rooster is retained through eight hens before an additional rooster is planned.'};
  }
  if (speciesId === 'goose_meat') {
    const baseFemales = Number(reproduction.breeding_females ?? 3);
    const breedingFemales = activeWhole(baseFemales * factor, factor);
    const breedingMales = active ? Math.max(1, Math.ceil(breedingFemales / 3)) : 0;
    const fertileEggs = breedingFemales * Number(reproduction.fertile_eggs_year ?? 24) / baseFemales;
    const goslings = fertileEggs * Number(reproduction.hatch_rate ?? .75) * Number(reproduction.gosling_survival ?? .80);
    const replacementFemales = active ? Math.max(1, whole(Number(reproduction.replacement_females_year ?? 1) * breedingFemales / baseFemales)) : 0;
    const replacementMales = active ? Number(reproduction.replacement_males_year ?? .25) * (breedingFemales / baseFemales) : 0;
    const harvestable = Math.max(0, goslings - replacementFemales - replacementMales);
    const canonicalHarvestable = 14.4 - 1 - .25;
    return {breeding_females: breedingFemales, breeding_males: breedingMales, fertile_eggs_year: fertileEggs, goslings_hatched_and_surviving_year: goslings, replacement_females_year: replacementFemales, replacement_males_year: replacementMales, animals_available_for_harvest_year: harvestable, feed_scale: breedingFemales / baseFemales, output_scale: harvestable / canonicalHarvestable, housing_scale: (breedingFemales + breedingMales) / 4, gander_capacity_females: 3, gander_capacity_note: 'One breeding male is retained through three females before an additional male is planned.'};
  }
  if (speciesId === 'goat_meat') {
    const baseFemales = Number(reproduction.breeding_does ?? 2);
    const breedingFemales = activeWhole(baseFemales * factor, factor);
    const breedingMales = active ? Math.max(1, Math.ceil(breedingFemales / 8)) : 0;
    const kidsBorn = breedingFemales * Number(reproduction.kids_year ?? 3) / baseFemales;
    const kidsSurviving = kidsBorn * Number(reproduction.kid_survival ?? .85);
    const replacementFemales = active ? Math.max(1, whole(Number(reproduction.replacement_does_year ?? .5) * breedingFemales / baseFemales)) : 0;
    const replacementMales = active ? Number(reproduction.replacement_bucks_year ?? .1) * (breedingFemales / baseFemales) : 0;
    const harvestable = Math.max(0, kidsSurviving - replacementFemales - replacementMales);
    const canonicalHarvestable = 2.55 - 1 - .1;
    return {breeding_females: breedingFemales, breeding_males: breedingMales, kids_born_year: kidsBorn, kids_surviving_year: kidsSurviving, replacement_females_year: replacementFemales, replacement_males_year: replacementMales, animals_available_for_harvest_year: harvestable, feed_scale: breedingFemales / baseFemales, output_scale: harvestable / canonicalHarvestable, housing_scale: (breedingFemales + breedingMales) / 3, buck_capacity_does: 8, buck_capacity_note: 'One breeding buck is retained through eight does before an additional buck is planned.'};
  }
  if (speciesId === 'chicken_meat') {
    const productionAnimals = activeWhole(25 * factor, factor);
    return {production_animals_year: productionAnimals, feed_scale: productionAnimals / 25, output_scale: productionAnimals / 25, housing_scale: productionAnimals / 25};
  }
  return {feed_scale: factor, output_scale: factor, housing_scale: factor};
}

export function calculateLivestockReproductiveLedger({speciesId, scale = 1} = {}) {
  const animal = LIVESTOCK_SPECIES[speciesId];
  const reproduction = animal?.reproduction;
  if (!animal || !reproduction) return {self_replacing: false, external_replacement_animals_year: null, feed_all_generations_included: false, status: 'reproduction ledger unavailable'};
  const population = livestockPopulation(speciesId, scale);
  const external = Number(reproduction.external_replacement_animals_year ?? reproduction.external_replacement_chicks_year ?? 0) * Number(scale);
  if (speciesId === 'chicken_eggs') {
    return {self_replacing: true, external_replacement_chicks_year: 0, external_replacement_pullets_year: 0, feed_all_generations_included: true, ...population, gross_eggs_year: population.gross_eggs_year, edible_eggs_year: population.edible_eggs_year, edible_eggs_kg_year: population.edible_eggs_kg_year, edible_meat_kg_year: population.edible_meat_kg_year, output: {eggs_year: population.edible_eggs_year, eggs_kg_year: population.edible_eggs_kg_year, edible_meat_kg_year: population.edible_meat_kg_year}, reference_breed: reproduction.reference_breed, evidence_status: reproduction.evidence_status};
  }
  return {self_replacing: reproduction.self_replacing !== false && external === 0, external_replacement_animals_year: external, feed_all_generations_included: reproduction.feed_all_generations_included === true, ...population, evidence_status: reproduction.evidence_status};
}

