export function calculateLivestockScenario({speciesId, rationId = 'arc_integrated', scale = 1, propertyFeedSupply = {}, siteCapability = {}, requireSelfSufficient = null} = {}) {
  const animal = LIVESTOCK_SPECIES[speciesId];
  const population = livestockPopulation(speciesId, scale);
  const feed = calculateFeedLedger({speciesId, rationId, scale: population.feed_scale ?? scale, propertyFeedSupply, siteCapability, requireSelfSufficient});
  const outputScale = Number(population.output_scale ?? scale);
  const reproduction = calculateLivestockReproductiveLedger({speciesId, scale});
  const output = {...Object.fromEntries(Object.entries(animal.output).map(([key, value]) => [key, round(Number(value) * outputScale)])), ...(reproduction.output ?? {})};
  const outputProfiles = animal.food_profile_id_by_output ?? {};
  const profileProtein = (profileId, kg) => Number(FOOD_NUTRIENT_PROFILES[profileId]?.protein_g_per_100g ?? 0) * Number(kg ?? 0) / 100;
  const edibleProtein = Object.keys(outputProfiles).length
    ? Object.entries(outputProfiles).reduce((sum, [product, profileId]) => sum + profileProtein(profileId, product === 'eggs' ? output.eggs_kg_year : output.edible_meat_kg_year), 0)
    : Number(animal.output.edible_protein_kg_year) * outputScale;
  if (Object.keys(outputProfiles).length) output.edible_protein_kg_year = round(edibleProtein);
  return {
    species_id: speciesId,
    label: animal.label,
    animal: animal.animal,
    unit_label: animal.unit_label,
    scale: Number(scale),
    livestock_scale: Number(scale),
    population,
    output,
    food_profile_id: animal.food_profile_id ?? null,
    food_profile_id_by_output: animal.food_profile_id_by_output ?? null,
    reproduction,
    feed,
    net_human_edible_protein_kg_year: round(edibleProtein - feed.human_edible_feed_protein_kg_year),
    human_edible_protein_conversion_efficiency: feed.human_edible_feed_protein_kg_year > 0 ? round(edibleProtein / feed.human_edible_feed_protein_kg_year, 4) : null,
    human_inedible_feed_fraction: feed.dry_matter_requirement_kg_year > 0 ? round(feed.human_inedible_feed_dm_kg_year / feed.dry_matter_requirement_kg_year) : 0,
    housing: {area_m2: round(animal.housing_area_m2 * Number(population.housing_scale ?? outputScale)), fencing_m: round(animal.fencing_m * Number(population.housing_scale ?? outputScale)), water_l_day: round(animal.water_l_day * Number(population.housing_scale ?? outputScale))},
    labour: (() => {
      // Fixed/variable splits are planning assumptions where no species study
      // reports household-scale labour directly. They preserve the canonical
      // reference total while avoiding four copies of setup work.
      const labourSplits = {rabbit_meat: {recurring_fixed: 60, recurring_variable: 120, processing_variable: 45}, chicken_eggs: {recurring_fixed: 70, recurring_variable: 140, processing_variable: 35}, chicken_meat: {recurring_fixed: 50, recurring_variable: 100, processing_variable: 60}, goose_meat: {recurring_fixed: 60, recurring_variable: 100, processing_variable: 36}, goat_meat: {recurring_fixed: 100, recurring_variable: 160, processing_variable: 50}};
      const split = labourSplits[speciesId] ?? {recurring_fixed: 0, recurring_variable: animal.labour_hours_year, processing_variable: animal.slaughter_processing_hours_year};
      const recurringScale = Number(scale) > 0 ? Number(population.feed_scale ?? outputScale) : 0;
      const processingScale = Number(population.output_scale ?? outputScale);
      const recurringFixed = split.recurring_fixed * (Number(scale) > 0 ? 1 : 0);
      const recurringVariable = split.recurring_variable * recurringScale;
      const processing = split.processing_variable * processingScale;
      return {recurring_fixed_hours_year: round(recurringFixed), recurring_variable_hours_year: round(recurringVariable), recurring_hours_year: round(recurringFixed + recurringVariable), slaughter_processing_hours_year: round(processing), total_hours_year: round(recurringFixed + recurringVariable + processing), physical_intensity: animal.physical_labour, scaling_note: 'Fixed setup/care work is counted once per selected system; animal-dependent care and processing scale from the actual population.'};
    })(),
    manure_kg_year: round(animal.manure_kg_year * Number(population.feed_scale ?? outputScale)),
    production_start_year: animal.production_start_year,
    source: animal.sources,
    evidence_status: 'planning_synthesis_bounded_by_extension_and_government_guidance',
    notes: animal.notes
  };
}

export function calculateMinimumSelfReplacingLivestockSystem({speciesId = 'rabbit_meat', rationId = 'arc_integrated', propertyFeedSupply = {}, siteCapability = {}} = {}) {
  const definition = MINIMUM_SELF_REPLACING_SYSTEMS[speciesId];
  if (!definition) throw new Error(`No minimum self-replacing system is defined for ${speciesId}`);
  return calculateLivestockScenario({speciesId, rationId, scale: definition.minimum_scale, propertyFeedSupply, siteCapability, requireSelfSufficient: true});
}

export function calculateNutrientFoodSystem({foodEvidence, demandGJ, proteinDemandKgYear, members = [], siteCapability, livestockMode = 'plants_only', rationId = 'arc_integrated', livestockScale, establishmentYears = [1, 2, 3, 5, 8, 10, 15, 'mature']} = {}) {
  if (!foodEvidence) throw new Error('nutrient food system requires canonical food evidence');
  const {calculateFoodSystem} = siteCapability?.calculateFoodSystem ? siteCapability : {};
  if (typeof calculateFoodSystem !== 'function') throw new Error('nutrient food system requires calculateFoodSystem in siteCapability');
  const plantOnly = calculateFoodSystem(foodEvidence, demandGJ, siteCapability);
  const proteinTarget = Number(proteinDemandKgYear ?? 0);
  const modes = livestockMode === 'plants_only' ? [] : livestockMode === 'mixed_rabbit_eggs' ? ['rabbit_meat', 'chicken_eggs'] : [livestockMode];
  const effectiveLivestockScale = deriveLivestockScale({foodDemandGJYear: demandGJ, livestockMode, livestockScale});
  const livestockSystemCount = deriveLivestockSystemCount({livestockMode});
  const livestockScalingBasis = livestockMode === 'plants_only'
    ? 'plants_only_zero_systems'
    : livestockScale !== undefined && livestockScale !== null
      ? 'explicit_sensitivity_override'
      : LIVESTOCK_SCALING_BASIS;
  const animalOutputs = modes.map((speciesId) => calculateLivestockScenario({speciesId, rationId, scale: effectiveLivestockScale, propertyFeedSupply: {}, siteCapability}));
  const animalEnergy = animalOutputs.reduce((sum, row) => sum + Number(row.output.food_energy_gj_year ?? 0), 0);
  const animalProtein = animalOutputs.reduce((sum, row) => sum + Number(row.output.edible_protein_kg_year ?? 0), 0);
  const plantDemandGJ = Math.max(0, Number(demandGJ) - animalEnergy);
  const plantFood = plantDemandGJ === Number(demandGJ) ? plantOnly : calculateFoodSystem(foodEvidence, plantDemandGJ, siteCapability);
  const plantProtein = Number(plantFood.macro_delivered_to_household?.protein_kg ?? 0);
  const totalProtein = plantProtein + animalProtein;
  const deficit = Math.max(0, proteinTarget - totalProtein);
  const propertyFeed = derivePropertyFeedSupply({foodSystem: plantFood});
  const remainingPropertyFeed = {...propertyFeed};
  const animals = animalOutputs.map((row) => {
    const result = calculateLivestockScenario({speciesId: row.species_id, rationId, scale: row.scale, propertyFeedSupply: remainingPropertyFeed, siteCapability});
    for (const feedRow of result.feed.rows) remainingPropertyFeed[feedRow.stream_id] = Math.max(0, Number(remainingPropertyFeed[feedRow.stream_id] ?? 0) - Number(feedRow.on_property_dm_kg ?? 0));
    return result;
  });
  const annualFeed = animals.reduce((sum, row) => sum + row.feed.dry_matter_requirement_kg_year, 0);
  const winterFeed = animals.reduce((sum, row) => sum + row.feed.winter_stored_feed_required_kg_year, 0);
  const purchasedFeed = animals.reduce((sum, row) => sum + row.feed.purchased_dry_matter_kg_year, 0);
  const dedicatedFeedLand = animals.reduce((sum, row) => sum + row.feed.additional_dedicated_feed_land_ha, 0);
  const feedDeficit = animals.reduce((sum, row) => sum + row.feed.feed_deficit_dm_kg_year, 0);
  const feedSelfSufficiency = animals.every((row) => row.feed.feed_self_sufficiency) && purchasedFeed === 0 && feedDeficit === 0;
  const reproductiveSelfSufficiency = animals.every((row) => row.reproduction?.self_replacing === true && row.reproduction?.feed_all_generations_included === true);
  const proteinCoverage = proteinTarget > 0 ? totalProtein / proteinTarget : 1;
  const nutrientCompleteness = calculateFoodNutrientAdequacy({members, plantFood, animals, energyGJ: demandGJ});
  const animalOutputByYear = Object.fromEntries(establishmentYears.map((year) => {
    const activeAnimals = animals.filter((animal) => year === 'mature' || Number(year) >= Number(animal.production_start_year ?? 1));
    return [String(year), {
      food_energy_gj_year: round(activeAnimals.reduce((sum, row) => sum + Number(row.output.food_energy_gj_year ?? 0), 0)),
      protein_kg_year: round(activeAnimals.reduce((sum, row) => sum + Number(row.output.edible_protein_kg_year ?? 0), 0)),
      active_species: activeAnimals.map((row) => row.species_id)
    }];
  }));
  // Low-level nutrient screening may be called without household members. In
  // that case there is no absolute household requirement to test; the full
  // household API always supplies members and performs the requirement check.
  const absoluteAminoAdequacy = members.length === 0 || nutrientCompleteness.amino_acid_pattern?.absolute_adequacy === true;
  return {
    contract_version: LIVESTOCK_CONTRACT_VERSION,
    mode: livestockMode,
    ration_id: rationId,
    livestock_system_count: livestockSystemCount,
    livestock_scale: round(effectiveLivestockScale),
    livestock_scaling_basis: livestockScalingBasis,
    protein_demand_kg_year: round(proteinTarget),
    plant_only: {food_energy_gj_year: round(demandGJ), protein_kg_year: round(plantOnly.macro_delivered_to_household?.protein_kg ?? 0), food_area_ha: plantOnly.required_food_area_ha},
    plant_food: plantFood,
    plant_energy_demand_gj_year: round(plantDemandGJ),
    animal_food_energy_gj_year: round(animalEnergy),
    animal_protein_kg_year: round(animalProtein),
    animal_output_by_year: animalOutputByYear,
    plant_protein_kg_year: round(plantProtein),
    total_protein_kg_year: round(totalProtein),
    protein_deficit_kg_year: round(deficit),
    protein_coverage_ratio: round(proteinCoverage),
    protein_adequacy: proteinCoverage >= 1,
    animals,
    feed: {property_supply: propertyFeed, annual_feed_required_kg: round(annualFeed), fresh_growing_season_feed_kg: round(Math.max(0, annualFeed - winterFeed)), winter_stored_feed_required_kg: round(winterFeed), winter_stored_feed_available_kg: round(animals.reduce((sum, row) => sum + row.feed.winter_stored_feed_available_kg_year, 0)), winter_feed_deficit_kg: round(animals.reduce((sum, row) => sum + row.feed.winter_feed_deficit_kg_year, 0)), storage_loss_kg: round(animals.reduce((sum, row) => sum + row.feed.storage_loss_kg_year, 0)), purchased_feed_required_kg: round(purchasedFeed), purchased_feed_dm_kg_year: round(purchasedFeed), property_grown_dedicated_feed_dm_kg_year: round(animals.reduce((sum, row) => sum + row.feed.property_grown_dedicated_feed_dm_kg_year, 0)), human_edible_feed_protein_consumed_kg: round(animals.reduce((sum, row) => sum + row.feed.human_edible_feed_protein_kg_year, 0)), human_inedible_feed_dm_kg: round(animals.reduce((sum, row) => sum + row.feed.human_inedible_feed_dm_kg_year, 0)), additional_dedicated_feed_land_ha: round(dedicatedFeedLand), feed_deficit_dm_kg_year: round(feedDeficit), feed_self_sufficiency: feedSelfSufficiency, external_feed_energy_gj_year: round(animals.reduce((sum, row) => sum + row.feed.feed_energy_import_gj_year, 0)), additional_dedicated_feed_land_if_no_purchased_substitution_ha: round(dedicatedFeedLand), double_counting_note: propertyFeed.double_counting_rule},
    labour: {recurring_hours_year: round(animals.reduce((sum, row) => sum + row.labour.recurring_hours_year, 0)), slaughter_processing_hours_year: round(animals.reduce((sum, row) => sum + row.labour.slaughter_processing_hours_year, 0)), livestock_hours_year: round(animals.reduce((sum, row) => sum + row.labour.total_hours_year, 0))},
    feed_self_sufficiency: feedSelfSufficiency,
    energy_adequacy: Number(plantFood.delivered_food_energy_gj ?? 0) + animalEnergy >= Number(demandGJ) - 1e-9,
    nutrient_completeness: nutrientCompleteness,
    reproductive_self_sufficiency: reproductiveSelfSufficiency,
    optimizer_eligible: proteinCoverage >= 1 && absoluteAminoAdequacy && Number(demandGJ) > 0 && feedSelfSufficiency && (livestockMode === 'plants_only' || reproductiveSelfSufficiency) && purchasedFeed === 0 && feedDeficit === 0,
    optimizer_note: livestockMode === 'plants_only' ? 'Plants-only is a valid baseline. Livestock is not required unless it improves a selected nutrient, land or labour objective.' : (!reproductiveSelfSufficiency ? 'This livestock option is non-canonical because the production population is not self-replacing or all generations are not fed.' : (!feedSelfSufficiency ? 'This livestock option is not ARC-feasible because the property cannot supply all dietary feed without imports.' : (deficit > 0 ? 'This on-site animal option supplies part of the remaining total-protein deficit; quality and micronutrients remain unresolved.' : 'This explicit on-site animal option meets the modeled total-protein target, but it is not automatically land-optimal.'))),
    evidence_boundary: 'Feed quantities, edible outputs and property co-product yields are bounded planning syntheses from government/extension sources, not Grey-Bruce household trials. Human-edible feed competition is tracked separately from total feed conversion.'
  };
}

export function compareNutrientFoodSystems({foodEvidence, demandGJ, proteinDemandKgYear, members = [], siteCapability} = {}) {
  const modes = ['plants_only', 'rabbit_meat', 'chicken_eggs', 'chicken_meat', 'goose_meat', 'goat_meat', 'mixed_rabbit_eggs'];
  const rationIds = ['conventional_reference', 'low_food_competition', 'arc_integrated'];
  const rows = modes.flatMap((mode) => rationIds.map((rationId) => calculateNutrientFoodSystem({foodEvidence, demandGJ, proteinDemandKgYear, members, siteCapability, livestockMode: mode, rationId}))).filter((row) => row.mode === 'plants_only' ? row.ration_id === 'arc_integrated' : true);
  const eligible = rows.filter((row) => row.protein_adequacy && row.energy_adequacy && row.optimizer_eligible && row.feed_self_sufficiency);
  const foodFeedArea = (row) => Number(row.plant_food.required_food_area_ha ?? 0) + Number(row.feed.additional_dedicated_feed_land_ha ?? 0);
  const labour = (row) => Number(row.labour?.livestock_hours_year ?? 0);
  const edibleCompetition = (row) => Number(row.feed.human_edible_feed_protein_consumed_kg ?? 0);
  const externalInputs = (row) => Number((row.nutrient_completeness?.external_inputs ?? []).length);
  const nutritionalCompleteness = (row) => Object.values(row.nutrient_completeness?.nutrients ?? {}).filter((item) => item.status === 'adequate from property-produced food').length + (row.nutrient_completeness?.amino_acid_pattern?.absolute_adequacy ? Object.keys(row.nutrient_completeness.amino_acid_pattern.rows).length : 0);
  const complexity = (row) => row.mode === 'plants_only' ? 0 : row.mode === 'mixed_rabbit_eggs' ? 2 : 1;
  const bestBy = (metric) => eligible.reduce((bestRow, row) => !bestRow || metric(row) < metric(bestRow) ? row : bestRow, null);
  const bestByDescending = (metric) => eligible.reduce((bestRow, row) => !bestRow || metric(row) > metric(bestRow) ? row : bestRow, null);
  const best = bestBy(foodFeedArea);
  const objectiveRow = (row, value, unit) => row ? {mode: row.mode, ration_id: row.ration_id, value, unit} : null;
  const metrics = (row) => ({food_feed_area_ha: foodFeedArea(row), labour_hours_year: labour(row), external_nutrient_inputs: externalInputs(row), human_edible_feed_protein_kg_year: edibleCompetition(row), nutritional_completeness_score: nutritionalCompleteness(row), complexity_units: complexity(row)});
  const pareto = eligible.filter((candidate) => {
    const a = metrics(candidate);
    return !eligible.some((other) => {
      if (other === candidate) return false;
      const b = metrics(other);
      const noWorse = b.food_feed_area_ha <= a.food_feed_area_ha && b.labour_hours_year <= a.labour_hours_year && b.external_nutrient_inputs <= a.external_nutrient_inputs && b.human_edible_feed_protein_kg_year <= a.human_edible_feed_protein_kg_year && b.complexity_units <= a.complexity_units && b.nutritional_completeness_score >= a.nutritional_completeness_score;
      const strictlyBetter = b.food_feed_area_ha < a.food_feed_area_ha || b.labour_hours_year < a.labour_hours_year || b.external_nutrient_inputs < a.external_nutrient_inputs || b.human_edible_feed_protein_kg_year < a.human_edible_feed_protein_kg_year || b.complexity_units < a.complexity_units || b.nutritional_completeness_score > a.nutritional_completeness_score;
      return noWorse && strictlyBetter;
    });
  }).map((row) => ({mode: row.mode, ration_id: row.ration_id, metrics: metrics(row)}));
  return {
    rows,
    eligible_rows: eligible.map((row) => ({mode: row.mode, ration_id: row.ration_id, metrics: metrics(row)})),
    objectives: {
      lowest_food_feed_area: objectiveRow(best, best ? foodFeedArea(best) : null, 'ha'),
      lowest_peak_productive_land: {status: 'requires full household transition context'},
      lowest_mature_productive_land: {status: 'requires full household transition context'},
      lowest_labour: objectiveRow(bestBy(labour), bestBy(labour) ? labour(bestBy(labour)) : null, 'hours/year'),
      lowest_external_nutrient_dependence: objectiveRow(bestBy(externalInputs), bestBy(externalInputs) ? externalInputs(bestBy(externalInputs)) : null, 'tracked nutrients'),
      lowest_human_edible_feed_competition: objectiveRow(bestBy(edibleCompetition), bestBy(edibleCompetition) ? edibleCompetition(bestBy(edibleCompetition)) : null, 'kg protein/year'),
      maximum_nutritional_completeness: objectiveRow(bestByDescending(nutritionalCompleteness), bestByDescending(nutritionalCompleteness) ? nutritionalCompleteness(bestByDescending(nutritionalCompleteness)) : null, 'tracked adequacy rows'),
      lowest_complexity: objectiveRow(bestBy(complexity), bestBy(complexity) ? complexity(bestBy(complexity)) : null, 'system units'),
      note: 'No single best food system is implied. Peak and mature productive-land winners require the full establishment transition; Pareto rows retain distinct land, labour, external-input, feed-competition, completeness and complexity objectives.'
    },
    pareto_efficient_options: pareto,
    best: best ? {mode: best.mode, ration_id: best.ration_id, reason: 'Lowest modeled plant-food plus on-site dedicated-feed screening area among eligible rows; not a universal optimum.', objective: 'food_feed_area_screening'} : null
  };
}
